#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048

static size_t url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, o = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            char hi = src[i + 1];
            char lo = src[i + 2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10));
            dst[o++] = (char)val;
            i += 3;
        } else {
            dst[o++] = c;
            ++i;
        }
    }
    dst[o] = '\0';
    return o;
}

int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_LINE];
    static char val[MAX_LINE];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    size_t linelen = strlen(line);
    while (linelen && (line[linelen - 1] == '\n' || line[linelen - 1] == '\r')) {
        line[--linelen] = '\0';
    }

    const char *p = line;
    while (*p) {
        const char *token_end = strchr(p, '&');
        if (!token_end)
            token_end = p + strlen(p);

        const char *eq = memchr(p, '=', token_end - p);
        const char *key_start, *val_start;
        size_t key_len, val_len;
        if (eq) {
            key_start = p;
            key_len = (size_t)(eq - p);
            val_start = eq + 1;
            val_len = (size_t)(token_end - val_start);
        } else {
            key_start = p;
            key_len = (size_t)(token_end - p);
            val_start = NULL;
            val_len = 0;
        }

        url_decode(key_start, key_len, key);
        if (val_len)
            url_decode(val_start, val_len, val);
        else
            val[0] = '\0';

        printf("%s=%s\n", key, val);

        p = (*token_end == '&') ? token_end + 1 : token_end;
    }
    return 0;
}
}
